import xml.etree.ElementTree as ET

from taf.sw.security.defensics.schemas.defensics_v2020_3.interoperability_probe import (
    InteroperabilityProbe,
    check_description_and_applied_params,
    check_groups,
    check_verdicts_params,
)


def create_last_interoperability_probe_object(data):
    raw_data = data.replace("\n", "").replace("\t", "")
    last_iteroperability_probe_params = LastInteroperabilityProbe.from_string(raw_data)
    return last_iteroperability_probe_params


class LastInteroperabilityProbe(InteroperabilityProbe):
    def __init__(self, total, interop, no_interop, unknown, description, applied, groups, result_groups, not_generated):
        super().__init__(total, interop, no_interop, unknown, description, applied, groups, result_groups)
        self.not_generated = not_generated

    @classmethod
    def from_string(cls, data):
        root = ET.fromstring(data)

        attributes = {"total": 0, "interop": 0, "no_interop": 0, "unknown": 0, "result_groups": "", "not_generated": 0}

        check_verdicts_params(root, attributes)
        check_groups(root, attributes)
        check_description_and_applied_params(root, attributes)

        return cls(**attributes)
